    def detect_category(self, market_text: str) -> Tuple[str, float, Dict]:
        """
        Detect market category with confidence score and metadata

        Returns:
            (category_name, confidence_score, metadata)
        """
        if not market_text:
            return 'other', 0.0, {}

        text_lower = market_text.lower()

        # Score all categories
        category_scores = {}

        for category, config in self.categories.items():
            score = 0.0
            matched_keywords = []

            for keyword in config['keywords']:
                if keyword in text_lower:
                    # Weight the score by keyword importance and frequency
                    score += config['weight']
                    matched_keywords.append(keyword)

                    # Bonus for exact matches or prominent keywords
                    if keyword in ['trump', 'bitcoin', 'nfl', 'ai']:
                        score += 1

            if score > 0:
                category_scores[category] = {
                    'score': score,
                    'keywords': matched_keywords,
                    'confidence': min(1.0, score / 5.0)  # Normalize confidence
                }

        if not category_scores:
            return 'other', 0.0, {'reason': 'no_keywords_matched'}

        # Find best match
        best_category = max(category_scores.keys(), key=lambda k: category_scores[k]['score'])
        best_data = category_scores[best_category]

        # Calculate confidence (0-1)
        confidence = best_data['confidence']

        # Add metadata
        metadata = {
            'matched_keywords': best_data['keywords'],
            'all_scores': {k: v['score'] for k, v in category_scores.items()},
            'risk_profile': self.risk_profiles.get(best_category, {'volatility': 'unknown', 'max_exposure': 100})
        }

        return best_category, confidence, metadata

    def get_category_limits(self, category: str) -> Dict:
        """Get position limits for a category"""
        default_limits = {
            'max_exposure': 100,
            'max_trades_per_day': 2,
            'volatility': 'medium'
        }

        if category in self.risk_profiles:
            limits = default_limits.copy()
            limits.update(self.risk_profiles[category])
            return limits

        return default_limits

    def get_all_categories(self) -> List[str]:
        """Get list of all available categories"""
        return list(self.categories.keys()) + ['other']

    def analyze_market_diversity(self, markets: List[str]) -> Dict:
        """Analyze the diversity of markets by category"""
        category_counts = {}
        category_confidence = {}

        for market in markets:
            category, confidence, metadata = self.detect_category(market)

            if category not in category_counts:
                category_counts[category] = 0
                category_confidence[category] = []

            category_counts[category] += 1
            category_confidence[category].append(confidence)

        # Calculate diversity score (0-1, higher = more diverse)
        num_categories = len(category_counts)
        max_possible = len(self.get_all_categories())
        diversity_score = min(1.0, num_categories / max_possible)

        return {
            'category_counts': category_counts,
            'category_confidences': {k: sum(v)/len(v) for k, v in category_confidence.items()},
            'diversity_score': diversity_score,
            'total_markets': len(markets),
            'categories_covered': num_categories
        }


