"""
Privacy Model for REALIZE-IO
Core privacy framework defining data classification, access levels, and protection mechanisms
"""

from enum import Enum, IntEnum
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Any
from datetime import datetime, timedelta
import json
import logging

logger = logging.getLogger(__name__)

class PrivacyLevel(IntEnum):
    """Privacy levels in order of increasing protection"""
    PUBLIC = 1      # Anonymized aggregated data shareable publicly
    COLLECTIVE = 2  # Shareable within 8OWLS collective (anonymized)
    PERSONAL = 3    # Local processing only, no sharing
    SENSITIVE = 4   # Encrypted at rest, special handling required
    RESTRICTED = 5  # Highest protection, minimal processing

class DataClassification(Enum):
    """Data classification categories"""
    HEALTH_VITALS = "health_vitals"           # Heart rate, sleep, steps
    HEALTH_SYMPTOMS = "health_symptoms"       # Symptoms, conditions, medical
    WEALTH_PERFORMANCE = "wealth_performance" # Returns, profit/loss ratios
    WEALTH_POSITIONS = "wealth_positions"     # Specific holdings, amounts
    PRODUCTIVITY_METRICS = "productivity_metrics" # Focus time, completion rates
    PRODUCTIVITY_CONTENT = "productivity_content" # Actual work content
    SOCIAL_PATTERNS = "social_patterns"       # Interaction frequency, network size
    SOCIAL_CONTENT = "social_content"         # Messages, conversations
    SYSTEM_METADATA = "system_metadata"       # Timestamps, version info

# Default privacy levels for each data classification
DEFAULT_CLASSIFICATIONS = {
    DataClassification.HEALTH_VITALS: PrivacyLevel.PERSONAL,
    DataClassification.HEALTH_SYMPTOMS: PrivacyLevel.SENSITIVE,
    DataClassification.WEALTH_PERFORMANCE: PrivacyLevel.COLLECTIVE,
    DataClassification.WEALTH_POSITIONS: PrivacyLevel.RESTRICTED,
    DataClassification.PRODUCTIVITY_METRICS: PrivacyLevel.COLLECTIVE,
    DataClassification.PRODUCTIVITY_CONTENT: PrivacyLevel.SENSITIVE,
    DataClassification.SOCIAL_PATTERNS: PrivacyLevel.PERSONAL,
    DataClassification.SOCIAL_CONTENT: PrivacyLevel.RESTRICTED,
    DataClassification.SYSTEM_METADATA: PrivacyLevel.PUBLIC
}

@dataclass
class PrivacyRule:
    """A privacy rule defining how data should be handled"""
    classification: DataClassification
    privacy_level: PrivacyLevel
    retention_days: Optional[int] = None
    anonymization_required: bool = True
    encryption_required: bool = True
    sharing_allowed: bool = False
    logging_allowed: bool = True

    def allows_operation(self, operation: str, context: Dict[str, Any] = None) -> bool:
        """Check if an operation is allowed under this privacy rule"""
        context = context or {}

        if operation == "share":
            return self.sharing_allowed and self.privacy_level <= PrivacyLevel.COLLECTIVE
        elif operation == "log":
            return self.logging_allowed and self.privacy_level <= PrivacyLevel.PERSONAL
        elif operation == "process":
            return True  # All data can be processed locally
        elif operation == "export":
            return True  # User owns their data
        elif operation == "analyze":
            return self.privacy_level <= PrivacyLevel.PERSONAL
        else:
            return False

@dataclass
class DataPoint:
    """A single data point with privacy metadata"""
    id: str
    value: Any
    classification: DataClassification
    timestamp: datetime
    source: str
    metadata: Dict[str, Any]

    @property
    def privacy_level(self) -> PrivacyLevel:
        """Get the privacy level for this data point"""
        return DEFAULT_CLASSIFICATIONS.get(self.classification, PrivacyLevel.SENSITIVE)

    @property
    def privacy_rule(self) -> PrivacyRule:
        """Get the privacy rule that applies to this data point"""
        return PrivacyRule(
            classification=self.classification,
            privacy_level=self.privacy_level,
            anonymization_required=self.privacy_level >= PrivacyLevel.PERSONAL,
            encryption_required=self.privacy_level >= PrivacyLevel.PERSONAL,
            sharing_allowed=self.privacy_level <= PrivacyLevel.COLLECTIVE,
            logging_allowed=self.privacy_level <= PrivacyLevel.PERSONAL
        )

class PrivacyModel:
    """Central privacy model for REALIZE-IO"""

    def __init__(self, config_path: Optional[str] = None):
        self.rules: Dict[DataClassification, PrivacyRule] = {}
        self.user_overrides: Dict[str, PrivacyLevel] = {}
        self.audit_trail: List[Dict[str, Any]] = []

        # Load default rules
        self._load_default_rules()

        # Load user configuration if available
        if config_path:
            self._load_user_config(config_path)

    def _load_default_rules(self):
        """Load default privacy rules"""
        for classification, level in DEFAULT_CLASSIFICATIONS.items():
            self.rules[classification] = PrivacyRule(
                classification=classification,
                privacy_level=level,
                retention_days=365,  # 1 year default retention
                anonymization_required=level >= PrivacyLevel.PERSONAL,
                encryption_required=level >= PrivacyLevel.PERSONAL,
                sharing_allowed=level <= PrivacyLevel.COLLECTIVE,
                logging_allowed=level <= PrivacyLevel.PERSONAL
            )

    def _load_user_config(self, config_path: str):
        """Load user privacy configuration overrides"""
        try:
            with open(config_path, 'r') as f:
                config = json.load(f)

            for class_name, level_name in config.get('privacy_overrides', {}).items():
                try:
                    classification = DataClassification(class_name)
                    privacy_level = PrivacyLevel[level_name.upper()]
                    self.user_overrides[classification.value] = privacy_level

                    # Update the rule
                    if classification in self.rules:
                        self.rules[classification].privacy_level = privacy_level
                        self.rules[classification].sharing_allowed = privacy_level <= PrivacyLevel.COLLECTIVE
                        self.rules[classification].encryption_required = privacy_level >= PrivacyLevel.PERSONAL

                except (ValueError, KeyError) as e:
                    logger.warning(f"Invalid privacy override: {class_name}={level_name}, {e}")

        except FileNotFoundError:
            logger.info(f"No privacy config found at {config_path}, using defaults")
        except Exception as e:
            logger.error(f"Error loading privacy config: {e}")

    def get_privacy_rule(self, classification: DataClassification) -> PrivacyRule:
        """Get privacy rule for a data classification"""
        return self.rules.get(classification, PrivacyRule(
            classification=classification,
            privacy_level=PrivacyLevel.SENSITIVE,
            anonymization_required=True,
            encryption_required=True,
            sharing_allowed=False
        ))

    def can_operation(self, data_point: DataPoint, operation: str, context: Dict[str, Any] = None) -> bool:
        """Check if an operation is allowed on a data point"""
        rule = self.get_privacy_rule(data_point.classification)
        allowed = rule.allows_operation(operation, context)

        # Log the access attempt
        self._audit_log(data_point, operation, allowed, context)

        return allowed

    def classify_data(self, data: Dict[str, Any], source: str) -> DataClassification:
        """Automatically classify data based on content and source"""

        # Check source patterns
        if source.startswith('apple_health'):
            if any(key in data for key in ['heart_rate', 'steps', 'sleep_hours']):
                return DataClassification.HEALTH_VITALS
            else:
                return DataClassification.HEALTH_SYMPTOMS

        elif source.startswith('joule') or 'trading' in source:
            if any(key in data for key in ['win_rate', 'profit_factor', 'daily_pnl']):
                return DataClassification.WEALTH_PERFORMANCE
            else:
                return DataClassification.WEALTH_POSITIONS

        elif source.startswith('nats') or 'productivity' in source:
            if any(key in data for key in ['focus_time', 'completion_rate']):
                return DataClassification.PRODUCTIVITY_METRICS
            else:
                return DataClassification.PRODUCTIVITY_CONTENT

        elif 'social' in source or 'communication' in source:
            if any(key in data for key in ['interaction_count', 'network_size']):
                return DataClassification.SOCIAL_PATTERNS
            else:
                return DataClassification.SOCIAL_CONTENT

        # Default to system metadata
        return DataClassification.SYSTEM_METADATA

    def get_sharing_policy(self) -> Dict[str, Any]:
        """Get current sharing policy summary"""
        shareable_categories = []
        local_only_categories = []

        for classification, rule in self.rules.items():
            if rule.sharing_allowed:
                shareable_categories.append(classification.value)
            else:
                local_only_categories.append(classification.value)

        return {
            'last_updated': datetime.now().isoformat(),
            'shareable_anonymized': shareable_categories,
            'local_only': local_only_categories,
            'user_controls': 'full',
            'data_portability': 'complete',
            'deletion_rights': 'immediate'
        }

    def _audit_log(self, data_point: DataPoint, operation: str, allowed: bool, context: Dict[str, Any] = None):
        """Log privacy-related operations for audit trail"""
        audit_entry = {
            'timestamp': datetime.now().isoformat(),
            'data_classification': data_point.classification.value,
            'operation': operation,
            'allowed': allowed,
            'privacy_level': data_point.privacy_level.name,
            'context_type': type(context).__name__ if context else None
        }

        self.audit_trail.append(audit_entry)

        # Keep only last 1000 audit entries
        if len(self.audit_trail) > 1000:
            self.audit_trail = self.audit_trail[-1000:]

    def export_privacy_report(self) -> Dict[str, Any]:
        """Export comprehensive privacy report for user review"""
        return {
            'model_version': '1.0',
            'generated_at': datetime.now().isoformat(),
            'privacy_rules': {
                classification.value: {
                    'privacy_level': rule.privacy_level.name,
                    'sharing_allowed': rule.sharing_allowed,
                    'encryption_required': rule.encryption_required,
                    'retention_days': rule.retention_days
                }
                for classification, rule in self.rules.items()
            },
            'user_overrides': self.user_overrides,
            'recent_audit_entries': self.audit_trail[-100:] if self.audit_trail else [],
            'sharing_summary': self.get_sharing_policy()
        }

"""
Data Anonymization for REALIZE-IO
Provides multiple anonymization strategies for different types of personal data
"""

from enum import Enum
from typing import Any, Dict, List, Optional, Union
import hashlib
import random
import math
from datetime import datetime, timedelta
import json
import logging

from .privacy_model import DataClassification, PrivacyLevel

logger = logging.getLogger(__name__)

class AnonymizationStrategy(Enum):
    """Different strategies for anonymizing data"""
    NONE = "none"                    # No anonymization
    HASH = "hash"                    # Replace with hash
    GENERALIZE = "generalize"        # Reduce precision
    NOISE = "noise"                  # Add statistical noise
    BUCKET = "bucket"                # Group into ranges
    SUPPRESS = "suppress"            # Remove entirely
    K_ANONYMITY = "k_anonymity"      # K-anonymity grouping

class DataAnonymizer:
    """Handles anonymization of personal data for sharing"""

    def __init__(self, user_id: str = "default"):
        self.user_id = user_id
        self.salt = self._generate_salt()

        # Define anonymization strategies per data classification
        self.strategies = {
            DataClassification.HEALTH_VITALS: AnonymizationStrategy.GENERALIZE,
            DataClassification.HEALTH_SYMPTOMS: AnonymizationStrategy.SUPPRESS,
            DataClassification.WEALTH_PERFORMANCE: AnonymizationStrategy.GENERALIZE,
            DataClassification.WEALTH_POSITIONS: AnonymizationStrategy.SUPPRESS,
            DataClassification.PRODUCTIVITY_METRICS: AnonymizationStrategy.GENERALIZE,
            DataClassification.PRODUCTIVITY_CONTENT: AnonymizationStrategy.SUPPRESS,
            DataClassification.SOCIAL_PATTERNS: AnonymizationStrategy.BUCKET,
            DataClassification.SOCIAL_CONTENT: AnonymizationStrategy.SUPPRESS,
            DataClassification.SYSTEM_METADATA: AnonymizationStrategy.NONE
        }

    def _generate_salt(self) -> str:
        """Generate a consistent salt for this user"""
        return hashlib.sha256(f"realize_io_{self.user_id}".encode()).hexdigest()[:16]

    def anonymize_data_point(self, data: Dict[str, Any], classification: DataClassification) -> Dict[str, Any]:
        """Anonymize a single data point according to its classification"""
        strategy = self.strategies.get(classification, AnonymizationStrategy.SUPPRESS)

        if strategy == AnonymizationStrategy.NONE:
            return data
        elif strategy == AnonymizationStrategy.SUPPRESS:
            return self._suppress_data(data, classification)
        elif strategy == AnonymizationStrategy.HASH:
            return self._hash_data(data)
        elif strategy == AnonymizationStrategy.GENERALIZE:
            return self._generalize_data(data, classification)
        elif strategy == AnonymizationStrategy.NOISE:
            return self._add_noise(data)
        elif strategy == AnonymizationStrategy.BUCKET:
            return self._bucket_data(data, classification)
        else:
            logger.warning(f"Unknown anonymization strategy: {strategy}")
            return self._suppress_data(data, classification)

    def _suppress_data(self, data: Dict[str, Any], classification: DataClassification) -> Dict[str, Any]:
        """Remove sensitive fields, keep only metadata"""
        anonymized = {
            'data_type': classification.value,
            'timestamp_hour': self._generalize_timestamp(data.get('timestamp')),
            'has_data': True
        }

        # Keep some non-sensitive aggregated info
        if 'count' in data:
            anonymized['count'] = data['count']
        if 'duration' in data:
            anonymized['duration_bucket'] = self._bucket_duration(data['duration'])

        return anonymized

    def _hash_data(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Replace identifiable values with hashes"""
        anonymized = {}

        for key, value in data.items():
            if key in ['user_id', 'id', 'name', 'email', 'phone']:
                # Hash identifiable fields
                anonymized[f"{key}_hash"] = hashlib.sha256(
                    f"{self.salt}_{value}".encode()
                ).hexdigest()[:16]
            elif key == 'timestamp':
                anonymized['timestamp_hour'] = self._generalize_timestamp(value)
            else:
                anonymized[key] = value

        return anonymized

    def _generalize_data(self, data: Dict[str, Any], classification: DataClassification) -> Dict[str, Any]:
        """Reduce precision of numerical data"""
        anonymized = {}

        for key, value in data.items():
            if key == 'timestamp':
                anonymized['timestamp_hour'] = self._generalize_timestamp(value)
            elif isinstance(value, (int, float)):
                anonymized[key] = self._generalize_number(value, classification, key)
            elif isinstance(value, str) and len(value) > 10:
                # Long strings might be content - hash them
                anonymized[f"{key}_hash"] = hashlib.sha256(
                    f"{self.salt}_{value}".encode()
                ).hexdigest()[:8]
            else:
                anonymized[key] = value

        return anonymized

    def _generalize_number(self, value: Union[int, float], classification: DataClassification, field: str) -> Union[int, float]:
        """Generalize numerical values based on context"""

        # Health vitals
        if classification == DataClassification.HEALTH_VITALS:
            if 'sleep' in field.lower():
                return round(value, 1)  # Sleep to 0.1 hour precision
            elif 'heart_rate' in field.lower():
                return round(value / 5) * 5  # Heart rate to nearest 5
            elif 'steps' in field.lower():
                return round(value / 1000) * 1000  # Steps to nearest 1000
            else:
                return round(value, 1)

        # Wealth performance (keep ratios but reduce precision)
        elif classification == DataClassification.WEALTH_PERFORMANCE:
            if 'rate' in field.lower() or 'ratio' in field.lower():
                return round(value, 2)  # Rates to 2 decimal places
            elif 'pnl' in field.lower() or 'profit' in field.lower():
                return round(value, 0)  # P&L to whole numbers
            else:
                return round(value, 1)

        # Productivity metrics
        elif classification == DataClassification.PRODUCTIVITY_METRICS:
            if 'time' in field.lower() or 'hours' in field.lower():
                return round(value, 1)  # Time to 0.1 hour precision
            elif 'count' in field.lower():
                return max(1, round(value / 5) * 5)  # Counts to nearest 5
            else:
                return round(value, 1)

        # Default generalization
        else:
            return round(value, 1)

    def _add_noise(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Add statistical noise to numerical values"""
        anonymized = {}

        for key, value in data.items():
            if isinstance(value, (int, float)) and key != 'timestamp':
                # Add noise proportional to the value (5% standard deviation)
                noise_std = abs(value * 0.05)
                noise = random.gauss(0, noise_std)
                anonymized[key] = value + noise
            else:
                anonymized[key] = value

        return anonymized

    def _bucket_data(self, data: Dict[str, Any], classification: DataClassification) -> Dict[str, Any]:
        """Group values into buckets/ranges"""
        anonymized = {}

        for key, value in data.items():
            if key == 'timestamp':
                anonymized['timestamp_hour'] = self._generalize_timestamp(value)
            elif isinstance(value, (int, float)):
                anonymized[key] = self._bucket_number(value, classification, key)
            else:
                anonymized[key] = value

        return anonymized

    def _bucket_number(self, value: Union[int, float], classification: DataClassification, field: str) -> str:
        """Put numerical values into buckets"""

        # Social patterns
        if classification == DataClassification.SOCIAL_PATTERNS:
            if 'count' in field.lower() or 'frequency' in field.lower():
                if value < 5:
                    return "low"
                elif value < 15:
                    return "medium"
                else:
                    return "high"
            elif 'hours' in field.lower() or 'time' in field.lower():
                if value < 1:
                    return "minimal"
                elif value < 3:
                    return "moderate"
                else:
                    return "significant"

        # Default bucketing
        if value < 10:
            return "0-10"
        elif value < 50:
            return "10-50"
        elif value < 100:
            return "50-100"
        else:
            return "100+"

    def _generalize_timestamp(self, timestamp: Any) -> str:
        """Generalize timestamps to hour precision"""
        if isinstance(timestamp, str):
            try:
                dt = datetime.fromisoformat(timestamp)
            except ValueError:
                return "unknown"
        elif isinstance(timestamp, datetime):
            dt = timestamp
        else:
            return "unknown"

        # Return hour of day and day of week only
        return f"{dt.strftime('%A')}_hour_{dt.hour}"

    def _bucket_duration(self, duration: Union[int, float]) -> str:
        """Bucket duration values"""
        if duration < 300:  # 5 minutes
            return "short"
        elif duration < 1800:  # 30 minutes
            return "medium"
        else:
            return "long"

    def anonymize_batch(self, data_points: List[Dict[str, Any]], classification: DataClassification) -> List[Dict[str, Any]]:
        """Anonymize a batch of data points"""
        return [self.anonymize_data_point(point, classification) for point in data_points]

    def create_k_anonymous_groups(self, data_points: List[Dict[str, Any]], k: int = 5) -> List[List[Dict[str, Any]]]:
        """Group data points to achieve k-anonymity"""
        if len(data_points) < k:
            return [data_points]  # Not enough data for k-anonymity

        # Simple grouping by similar attributes
        groups = []
        remaining = data_points.copy()

        while len(remaining) >= k:
            group = remaining[:k]
            groups.append(group)
            remaining = remaining[k:]

        # Add remaining items to the last group if it exists
        if remaining and groups:
            groups[-1].extend(remaining)
        elif remaining:
            groups.append(remaining)

        return groups

    def get_anonymization_summary(self) -> Dict[str, Any]:
        """Get summary of anonymization strategies in use"""
        return {
            'user_id_hash': hashlib.sha256(f"{self.salt}_{self.user_id}".encode()).hexdigest()[:8],
            'strategies': {
                classification.value: strategy.value 
                for classification, strategy in self.strategies.items()
            },
            'privacy_guarantees': {
                'no_direct_identifiers': True,
                'temporal_generalization': True,
                'numerical_precision_reduced': True,
                'sensitive_content_suppressed': True
            }
        }

"""
Consent Management for REALIZE-IO
Manages user consent for data collection, processing, and sharing
"""

from enum import Enum
from dataclasses import dataclass
from typing import Dict, List, Optional, Set
from datetime import datetime, timedelta
import json
import logging

from .privacy_model import DataClassification, PrivacyLevel

logger = logging.getLogger(__name__)

class ConsentType(Enum):
    """Types of consent that can be granted or revoked"""
    DATA_COLLECTION = "data_collection"
    LOCAL_PROCESSING = "local_processing"
    AGGREGATED_SHARING = "aggregated_sharing"
    ANONYMOUS_RESEARCH = "anonymous_research"
    COLLECTIVE_INSIGHTS = "collective_insights"
    SYSTEM_OPTIMIZATION = "system_optimization"
    FEATURE_IMPROVEMENTS = "feature_improvements"

@dataclass
class ConsentRecord:
    """A single consent record"""
    consent_type: ConsentType
    data_classification: Optional[DataClassification]
    granted: bool
    timestamp: datetime
    expires: Optional[datetime] = None
    context: Optional[str] = None
    version: str = "1.0"

    @property
    def is_valid(self) -> bool:
        """Check if consent is still valid"""
        if not self.granted:
            return False
        if self.expires and datetime.now() > self.expires:
            return False
        return True

class ConsentManager:
    """Manages all consent-related operations"""

    def __init__(self, user_id: str, storage_path: Optional[str] = None):
        self.user_id = user_id
        self.storage_path = storage_path or f"consent_{user_id}.json"
        self.consents: Dict[str, ConsentRecord] = {}
        self.consent_history: List[ConsentRecord] = []

        # Load existing consents
        self._load_consents()

        # Set up default consents (essential operations)
        self._initialize_default_consents()

    def _load_consents(self):
        """Load existing consent records from storage"""
        try:
            with open(self.storage_path, 'r') as f:
                data = json.load(f)

            for key, consent_data in data.get('consents', {}).items():
                consent = ConsentRecord(
                    consent_type=ConsentType(consent_data['consent_type']),
                    data_classification=DataClassification(consent_data['data_classification']) 
                        if consent_data.get('data_classification') else None,
                    granted=consent_data['granted'],
                    timestamp=datetime.fromisoformat(consent_data['timestamp']),
                    expires=datetime.fromisoformat(consent_data['expires']) 
                        if consent_data.get('expires') else None,
                    context=consent_data.get('context'),
                    version=consent_data.get('version', '1.0')
                )
                self.consents[key] = consent

            # Load history
            for consent_data in data.get('history', []):
                consent = ConsentRecord(
                    consent_type=ConsentType(consent_data['consent_type']),
                    data_classification=DataClassification(consent_data['data_classification']) 
                        if consent_data.get('data_classification') else None,
                    granted=consent_data['granted'],
                    timestamp=datetime.fromisoformat(consent_data['timestamp']),
                    expires=datetime.fromisoformat(consent_data['expires']) 
                        if consent_data.get('expires') else None,
                    context=consent_data.get('context'),
                    version=consent_data.get('version', '1.0')
                )
                self.consent_history.append(consent)

        except FileNotFoundError:
            logger.info(f"No existing consent file found at {self.storage_path}")
        except Exception as e:
            logger.error(f"Error loading consents: {e}")

    def _save_consents(self):
        """Save current consents to storage"""
        try:
            data = {
                'user_id': self.user_id,
                'last_updated': datetime.now().isoformat(),
                'consents': {
                    key: {
                        'consent_type': consent.consent_type.value,
                        'data_classification': consent.data_classification.value if consent.data_classification else None,
                        'granted': consent.granted,
                        'timestamp': consent.timestamp.isoformat(),
                        'expires': consent.expires.isoformat() if consent.expires else None,
                        'context': consent.context,
                        'version': consent.version
                    }
                    for key, consent in self.consents.items()
                },
                'history': [
                    {
                        'consent_type': consent.consent_type.value,
                        'data_classification': consent.data_classification.value if consent.data_classification else None,
                        'granted': consent.granted,
                        'timestamp': consent.timestamp.isoformat(),
                        'expires': consent.expires.isoformat() if consent.expires else None,
                        'context': consent.context,
                        'version': consent.version
                    }
                    for consent in self.consent_history[-100:]  # Keep last 100 history items
                ]
            }

            with open(self.storage_path, 'w') as f:
                json.dump(data, f, indent=2)

        except Exception as e:
            logger.error(f"Error saving consents: {e}")

    def _initialize_default_consents(self):
        """Set up essential default consents"""
        essential_consents = [
            (ConsentType.DATA_COLLECTION, None, "Essential for app functionality"),
            (ConsentType.LOCAL_PROCESSING, None, "Required for trajectory analysis"),
            (ConsentType.SYSTEM_OPTIMIZATION, None, "Improves performance and reliability")
        ]

        for consent_type, classification, context in essential_consents:
            key = self._consent_key(consent_type, classification)
            if key not in self.consents:
                self.grant_consent(consent_type, classification, context=context)

    def _consent_key(self, consent_type: ConsentType, classification: Optional[DataClassification] = None) -> str:
        """Generate a unique key for a consent record"""
        if classification:
            return f"{consent_type.value}_{classification.value}"
        return consent_type.value

    def grant_consent(self, 
                     consent_type: ConsentType, 
                     classification: Optional[DataClassification] = None,
                     expires: Optional[datetime] = None,
                     context: Optional[str] = None) -> bool:
        """Grant consent for a specific type and classification"""
        try:
            key = self._consent_key(consent_type, classification)

            # Check if consent already exists and update it
            old_consent = self.consents.get(key)
            if old_consent:
                self.consent_history.append(old_consent)

            consent = ConsentRecord(
                consent_type=consent_type,
                data_classification=classification,
                granted=True,
                timestamp=datetime.now(),
                expires=expires,
                context=context
            )

            self.consents[key] = consent
            self._save_consents()

            logger.info(f"Granted consent: {consent_type.value} for {classification.value if classification else 'all data'}")
            return True

        except Exception as e:
            logger.error(f"Error granting consent: {e}")
            return False

    def revoke_consent(self, 
                      consent_type: ConsentType, 
                      classification: Optional[DataClassification] = None,
                      context: Optional[str] = None) -> bool:
        """Revoke consent for a specific type and classification"""
        try:
            key = self._consent_key(consent_type, classification)

            if key not in self.consents:
                logger.warning(f"No consent found to revoke: {key}")
                return False

            # Move current consent to history
            old_consent = self.consents[key]
            self.consent_history.append(old_consent)

            # Create revocation record
            revocation = ConsentRecord(
                consent_type=consent_type,
                data_classification=classification,
                granted=False,
                timestamp=datetime.now(),
                context=context or "User revoked consent"
            )

            self.consents[key] = revocation
            self._save_consents()

            logger.info(f"Revoked consent: {consent_type.value} for {classification.value if classification else 'all data'}")
            return True

        except Exception as e:
            logger.error(f"Error revoking consent: {e}")
            return False

    def has_consent(self, 
                   consent_type: ConsentType, 
                   classification: Optional[DataClassification] = None) -> bool:
        """Check if consent is granted and valid"""
        key = self._consent_key(consent_type, classification)

        consent = self.consents.get(key)
        if not consent:
            return False

        return consent.is_valid

    def get_consents_for_classification(self, classification: DataClassification) -> List[ConsentRecord]:
        """Get all consents for a specific data classification"""
        relevant_consents = []

        for consent in self.consents.values():
            if consent.data_classification == classification or consent.data_classification is None:
                relevant_consents.append(consent)

        return relevant_consents

    def get_sharing_permissions(self) -> Dict[str, bool]:
        """Get current sharing permissions"""
        return {
            'aggregated_sharing': self.has_consent(ConsentType.AGGREGATED_SHARING),
            'anonymous_research': self.has_consent(ConsentType.ANONYMOUS_RESEARCH),
            'collective_insights': self.has_consent(ConsentType.COLLECTIVE_INSIGHTS),
            'feature_improvements': self.has_consent(ConsentType.FEATURE_IMPROVEMENTS)
        }

    def can_collect_data(self, classification: DataClassification) -> bool:
        """Check if data collection is allowed for a classification"""
        return self.has_consent(ConsentType.DATA_COLLECTION, classification) or \
               self.has_consent(ConsentType.DATA_COLLECTION, None)

    def can_process_data(self, classification: DataClassification) -> bool:
        """Check if data processing is allowed for a classification"""
        return self.has_consent(ConsentType.LOCAL_PROCESSING, classification) or \
               self.has_consent(ConsentType.LOCAL_PROCESSING, None)

    def can_share_data(self, classification: DataClassification, sharing_type: ConsentType) -> bool:
        """Check if data sharing is allowed"""
        if sharing_type not in [ConsentType.AGGREGATED_SHARING, ConsentType.ANONYMOUS_RESEARCH, 
                               ConsentType.COLLECTIVE_INSIGHTS]:
            return False

        return self.has_consent(sharing_type, classification) or \
               self.has_consent(sharing_type, None)

    def get_consent_summary(self) -> Dict[str, any]:
        """Get a summary of all current consents"""
        active_consents = {k: v for k, v in self.consents.items() if v.is_valid and v.granted}
        revoked_consents = {k: v for k, v in self.consents.items() if not v.granted}
        expired_consents = {k: v for k, v in self.consents.items() if v.granted and not v.is_valid}

        return {
            'user_id': self.user_id,
            'last_updated': max(c.timestamp for c in self.consents.values()).isoformat() if self.consents else None,
            'active_consents': len(active_consents),
            'revoked_consents': len(revoked_consents),
            'expired_consents': len(expired_consents),
            'total_history_entries': len(self.consent_history),
            'sharing_enabled': any(
                self.has_consent(ct) for ct in [
                    ConsentType.AGGREGATED_SHARING,
                    ConsentType.ANONYMOUS_RESEARCH,
                    ConsentType.COLLECTIVE_INSIGHTS
                ]
            ),
            'data_collection_enabled': any(
                self.has_consent(ConsentType.DATA_COLLECTION, classification) 
                for classification in DataClassification
            ) or self.has_consent(ConsentType.DATA_COLLECTION),
            'consents': {
                key: {
                    'granted': consent.granted,
                    'valid': consent.is_valid,
                    'granted_date': consent.timestamp.isoformat(),
                    'expires': consent.expires.isoformat() if consent.expires else None,
                    'context': consent.context
                }
                for key, consent in self.consents.items()
            }
        }

    def cleanup_expired_consents(self):
        """Remove expired consents and move to history"""
        expired_keys = []

        for key, consent in self.consents.items():
            if consent.granted and not consent.is_valid:
                expired_keys.append(key)

        for key in expired_keys:
            expired_consent = self.consents.pop(key)
            self.consent_history.append(expired_consent)
            logger.info(f"Moved expired consent to history: {key}")

        if expired_keys:
            self._save_consents()

    def export_consent_record(self) -> Dict[str, any]:
        """Export complete consent record for user review"""
        return {
            'export_timestamp': datetime.now().isoformat(),
            'user_id': self.user_id,
            'consent_version': '1.0',
            'current_consents': {
                key: {
                    'consent_type': consent.consent_type.value,
                    'data_classification': consent.data_classification.value if consent.data_classification else None,
                    'granted': consent.granted,
                    'valid': consent.is_valid,
                    'granted_date': consent.timestamp.isoformat(),
                    'expires': consent.expires.isoformat() if consent.expires else None,
                    'context': consent.context,
                    'version': consent.version
                }
                for key, consent in self.consents.items()
            },
            'consent_history': [
                {
                    'consent_type': consent.consent_type.value,
                    'data_classification': consent.data_classification.value if consent.data_classification else None,
                    'granted': consent.granted,
                    'granted_date': consent.timestamp.isoformat(),
                    'expires': consent.expires.isoformat() if consent.expires else None,
                    'context': consent.context,
                    'version': consent.version
                }
                for consent in self.consent_history
            ],
            'summary': self.get_consent_summary()
        }

