function setupRealTimeMetricsUpdates() {
    // Update metrics every 10 seconds to simulate real-time data
    setInterval(() => {
        updateRealTimeMetrics();
    }, 10000);

    // Animate metric cards on updates
    addMetricAnimations();
}

function updateRealTimeMetrics() {
    const data = loadData();
    const entries = data.subscribers.entries;

    if (entries.length > 0) {
        // Add some realistic variance to simulate real-time updates
        const lastEntry = entries[entries.length - 1];
        const today = new Date().toISOString().split('T')[0];

        if (lastEntry.date === today && Math.random() < 0.3) {
            // 30% chance of micro-update during the day
            const variance = Math.floor(Math.random() * 3) - 1; // -1, 0, or 1
            lastEntry.new += Math.max(0, variance);
            lastEntry.net = lastEntry.new - lastEntry.churned;
            lastEntry.total = Math.max(0, lastEntry.total + variance);

            saveData(data);

            // Update displays with animation
            updateStatsWithAnimation();
            updateKPIDashboard();

            // Trigger metric pulse animation
            triggerMetricPulse();
        }
    }
}

function updateStatsWithAnimation() {
    const data = loadData();
    const entries = data.subscribers.entries;

    // Get elements to animate
    const totalEl = document.getElementById('totalSubscribers');
    const weeklyEl = document.getElementById('weeklyNet');
    const monthlyEl = document.getElementById('monthlyNet');

    // Add pulse animation class
    [totalEl, weeklyEl, monthlyEl].forEach(el => {
        if (el) {
            el.classList.add('metric-updated');
            setTimeout(() => el.classList.remove('metric-updated'), 1000);
